import { Effect } from "effect"
import { readdir, stat } from "node:fs/promises"
import { homedir } from "node:os"
import { join } from "node:path"

export interface CacheEntry {
  readonly name: string
  readonly path: string
  readonly bytes: number
  readonly modifiedAt: Date
}

// Used only by the sibling list.ts and prune.ts cache commands.
export const resolveCacheRoot = (override?: string): string =>
  override ?? join(homedir(), ".forge", "artifact-cache")

export const readCacheEntries = (root: string) =>
  Effect.tryPromise({
    try: async (): Promise<ReadonlyArray<CacheEntry>> => {
      const children = await readdir(root, { withFileTypes: true })
      return Promise.all(
        children.filter((child) => child.isFile()).map(async (child) => {
          const path = join(root, child.name)
          const metadata = await stat(path)
          return {
            name: child.name,
            path,
            bytes: metadata.size,
            modifiedAt: metadata.mtime
          }
        })
      )
    },
    catch: (cause) => new Error(`Cannot read artifact cache at ${root}`, { cause })
  })

